(() => {
  // Remove only the exact fallbacks generated by the older importers. A real
  // explanation beginning with the answer and continuing with reasoning stays.
  function contentFor(explanation, answer) {
    const content = typeof explanation === 'string' ? explanation : '';
    const trimmed = content.trim();
    if (!trimmed || trimmed === '詳細解説準備中。' || trimmed === `正解: ${String(answer ?? '')}`) return '';
    return content;
  }

  // Presentation only: never update a question, score, history, sound or storage.
  function render(contentElement, explanation, answer, format) {
    if (!contentElement) return false;
    const content = contentFor(explanation, answer);
    const panel = contentElement.closest('[data-explanation-panel]') || contentElement.parentElement;
    contentElement.innerHTML = content ? (typeof format === 'function' ? format(content) : content) : '';
    if (panel) {
      panel.hidden = !content;
      panel.setAttribute('aria-hidden', String(!content));
    }
    return !!content;
  }

  window.QuizExplanation = { contentFor, render };
})();
